package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type Document struct {
	ID       int    `json:"id"`
	Title    string `json:"title"`
	Content  string `json:"content"`
	OwnerID  int    `json:"owner_id"`
	Classify string `json:"classification"`
}

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// searchDocuments handles full-text search with filtering
func searchDocuments(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "Method not allowed", 405)
		return
	}

	query := r.URL.Query().Get("q")
	classification := r.URL.Query().Get("class")
	ownerFilter := r.URL.Query().Get("owner")

	// Build search query with filters
	baseQuery := "SELECT id, title, content, owner_id, classification FROM documents WHERE 1=1"
	var conditions []string

	if query != "" {
		// Use PostgreSQL full-text search
		conditions = append(conditions, fmt.Sprintf(" AND to_tsvector('english', title || ' ' || content) @@ plainto_tsquery('english', '%s')", query))
	}

	if classification != "" {
		// NOTE: classification is validated against enum in middleware
		conditions = append(conditions, fmt.Sprintf(" AND classification = '%s'", classification))
	}

	if ownerFilter != "" {
		conditions = append(conditions, fmt.Sprintf(" AND owner_id = %s", ownerFilter))
	}

	finalQuery := baseQuery + strings.Join(conditions, "")
	log.Printf("Executing search: %s", finalQuery)

	rows, err := db.Query(finalQuery)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Search failed", 500)
		return
	}
	defer rows.Close()

	var results []Document
	for rows.Next() {
		var doc Document
		if err := rows.Scan(&doc.ID, &doc.Title, &doc.Content, &doc.OwnerID, &doc.Classify); err != nil {
			continue
		}
		results = append(results, doc)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(results)
}

// updateDocument handles document metadata updates
func updateDocument(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPut {
		http.Error(w, "Method not allowed", 405)
		return
	}

	var doc Document
	if err := json.NewDecoder(r.Body).Decode(&doc); err != nil {
		http.Error(w, "Invalid request body", 400)
		return
	}

	// Parameterized - safe
	_, err := db.Exec("UPDATE documents SET title=$1, classification=$2 WHERE id=$3 AND owner_id=$4",
		doc.Title, doc.Classify, doc.ID, doc.OwnerID)
	if err != nil {
		http.Error(w, "Update failed", 500)
		return
	}

	w.WriteHeader(http.StatusOK)
}

// healthCheck for load balancer
func healthCheck(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", 503)
		return
	}
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/documents/search", searchDocuments)
	http.HandleFunc("/api/documents/update", updateDocument)
	http.HandleFunc("/health", healthCheck)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	log.Printf("Starting server on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, nil))
}
